const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([-22.413665983340525, 63.8577134531586]);
  const point2 = ee.Geometry.Point([-22.4338, 63.8424]); // Grindavik approximate
  const date = '2024-01-16';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition - try MODIS Terra first
  let modisTerra = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(point1.union(point2));

  // Check if Terra has data
  let terraSize = modisTerra.size().getInfo();
  console.log(`MODIS Terra images for ${date}: ${terraSize}`);

  let lstImage;
  let source = 'Terra';

  if (terraSize === 0) {
    // Try MODIS Aqua
    let modisAqua = ee.ImageCollection('MODIS/061/MYD11A1')
      .filterDate(startDate, endDate)
      .filterBounds(point1.union(point2));

    let aquaSize = modisAqua.size().getInfo();
    console.log(`MODIS Aqua images for ${date}: ${aquaSize}`);

    if (aquaSize === 0) {
      console.log('No MODIS images found.');
      console.log('<answer>C1</answer>');
      return;
    }

    lstImage = modisAqua.first();
    source = 'Aqua';
  } else {
    lstImage = modisTerra.first();
  }

  console.log(`Using ${source} image.`);

  // 3. Processing: Mask clouds and convert LST to Celsius
  // LST_Day_1km band: scale 0.02, Kelvin to Celsius: (value * 0.02) - 273.15
  // QC_Day: bits 0-1 = LST quality, bits 2-3 = data quality
  function maskModisLST(image) {
    const lst = image.select('LST_Day_1km');
    const qc = image.select('QC_Day');

    // Extract quality bits
    const lstQuality = qc.bitwiseAnd(3); // bits 0-1
    const dataQuality = qc.rightShift(2).bitwiseAnd(3); // bits 2-3

    // Mask: LST produced (good) and data quality good or average
    const mask = lstQuality.eq(0).and(dataQuality.lte(1));

    // Apply scaling and conversion
    return lst.updateMask(mask)
      .multiply(0.02)
      .subtract(273.15)
      .rename('LST_Celsius');
  }

  const lstMasked = maskModisLST(lstImage);

  // 4. Extract temperatures at both points
  const scale = 1000; // MODIS resolution

  // Function to extract temperature and count valid pixels
  function extractTemp(point) {
    const result = lstMasked.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: point,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    });

    const temp = result.get('LST_Celsius_mean');
    const count = result.get('LST_Celsius_count');

    return {
      temp: temp.getInfo(),
      count: count.getInfo()
    };
  }

  const temp1 = extractTemp(point1);
  const temp2 = extractTemp(point2);

  console.log(`Point 1: Temp = ${temp1.temp !== null ? temp1.temp.toFixed(2) + '°C' : 'null'}, Valid pixels = ${temp1.count}`);
  console.log(`Point 2: Temp = ${temp2.temp !== null ? temp2.temp.toFixed(2) + '°C' : 'null'}, Valid pixels = ${temp2.count}`);

  // 5. Validation & Final Answer
  // Check for valid pixels
  if (temp1.count === 0 || temp2.count === 0) {
    console.log('No valid pixels after masking at one or both points.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for calculation failures
  if (temp1.temp === null || temp2.temp === null || 
      isNaN(temp1.temp) || isNaN(temp2.temp) ||
      Math.abs(temp1.temp) > 100 || Math.abs(temp2.temp) > 100) {
    console.log('Temperature calculation failed or out of valid range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare temperatures
  const isHigher = temp1.temp > temp2.temp;
  console.log(`Comparison: ${temp1.temp.toFixed(2)}°C > ${temp2.temp.toFixed(2)}°C ? ${isHigher}`);

  // Output final answer
  if (isHigher) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
